std::vector<std::pair<size_t, size_t>> colliding_pairs;
const size_t n = boxes.size();

// Brute-force collision detection (O(n^2) complexity)
for (size_t i = 0; i < n; ++i)
{
    for (size_t j = i + 1; j < n; ++j)
    {
        const auto& box1 = boxes[i];
        const auto& box2 = boxes[j];

        // Check for overlap in all 3 dimensions
        bool overlap_x = (box1.Max.x >= box2.Min.x) && (box1.Min.x <= box2.Max.x);
        bool overlap_y = (box1.Max.y >= box2.Min.y) && (box1.Min.y <= box2.Max.y);
        bool overlap_z = (box1.Max.z >= box2.Min.z) && (box1.Min.z <= box2.Max.z);

        if (overlap_x && overlap_y && overlap_z)
        {
            colliding_pairs.emplace_back(i, j);
        }
    }
}

return colliding_pairs;

